insert into public.registry_versions (hash, engine_version, metric_version, content)
values ('1b3ae2fe10d065ce', '0.6.0', 'ffd-0.6.0', '{"thresholds":{"capture.min_batter_px":{"value":250,"unit":"px standing height","rationale":"Below this a thigh spans under ~60 px, so a 2 px landmark error moves a joint angle by about 3°."},"capture.fail_batter_px":{"value":100,"unit":"px standing height","rationale":"Below this a thigh spans about 25 px: joint angles are uncertain by 6° or more, too coarse to grade."},"capture.min_fps_timing":{"value":60,"unit":"fps","rationale":"At 60 fps one frame is ~17 ms; below that contact and timing windows are coarser than the movements they describe."},"capture.min_fps_any":{"value":15,"unit":"fps","rationale":"Below 15 fps a defence spans too few frames to find the stroke. Real defences re-tracked at 15 and 10 fps kept the same verdict; timing is reported with one frame of uncertainty."},"capture.min_duration_ms":{"value":1200,"unit":"ms","rationale":"Needs setup, delivery and follow-through in one clip."},"capture.min_body_coverage":{"value":0.85,"unit":"fraction","rationale":"Batter must be visible in most frames."},"capture.fail_body_coverage":{"value":0.5,"unit":"fraction","rationale":"Batter missing from half the clip."},"capture.min_brightness":{"value":0.18,"unit":"luma","rationale":"Dark footage raises pose noise."},"capture.max_brightness":{"value":0.9,"unit":"luma","rationale":"Blown highlights hide the ball and bat edges."},"capture.min_contrast":{"value":0.08,"unit":"luma sd","rationale":"Flat images hide limb edges."},"capture.min_sharpness":{"value":0.012,"unit":"laplacian var","rationale":"Motion blur prevents bat and ball tracking."},"capture.max_background_motion":{"value":0.06,"unit":"fraction","rationale":"Hand-held shake corrupts displacement measures."},"tracking.joint_min_conf":{"value":0.5,"unit":"confidence","rationale":"Landmarks below this are treated as unobserved."},"tracking.bat_min_coverage":{"value":0.5,"unit":"fraction","rationale":"Bat path needs most of the swing."},"tracking.ball_min_points":{"value":4,"unit":"frames","rationale":"Fewer points cannot fix a trajectory."},"delivery.full_good_boundary_m":{"value":5.5,"unit":"m from batter''s stumps","rationale":"Provisional pace boundary; refit per bowler type."},"delivery.good_short_boundary_m":{"value":8,"unit":"m from batter''s stumps","rationale":"Provisional pace boundary; refit per bowler type."},"delivery.boundary_softness_m":{"value":0.9,"unit":"m","rationale":"Soft membership avoids hard cliffs at a boundary."},"delivery.short_height_rel":{"value":0.62,"unit":"stature","rationale":"Ball arriving above ~waist-to-chest height suggests short length."},"classifier.unknown_log_likelihood":{"value":-5.5,"unit":"log-lik","rationale":"If no prototype fits better than this, the clip is out of distribution."},"classifier.temperature":{"value":1.4,"unit":"","rationale":"Softens prototype scores; NOT an empirical calibration."},"ffd.accept.min_probability":{"value":0.8,"unit":"probability","rationale":"Acceptance is deliberately strict; false acceptance is release-blocking."},"ffd.accept.min_margin":{"value":0.3,"unit":"probability","rationale":"Top class must clearly beat the runner-up."},"ffd.accept.max_unknown":{"value":0.1,"unit":"probability","rationale":"Out-of-distribution mass must be small."},"ffd.accept.min_evidence_coverage":{"value":0.75,"unit":"fraction","rationale":"Most discriminative features must be observed."},"stroke.min_hand_speed":{"value":0.6,"unit":"× stature/s","rationale":"Below this peak hand speed, and without a front-foot stride, no batting stroke was played (a still pose, someone standing in shot)."},"ffd.min_head_drop":{"value":0.05,"unit":"× stature","rationale":"A front-foot defence goes forward and down into the ball: the head drops, or the hips do as the front knee bends (either is enough: a beginner may stay upright or keep the leg straight). Real defences lowered the head 0.17–0.39 × height; a stance and backlift with no stroke, 0.03."},"ffd.min_hip_drop":{"value":0.03,"unit":"× stature","rationale":"Hips: real defences 0.10–0.23 × height; a stance and backlift 0.02; back-foot shots about 0."},"stroke.max_zoom_for_rejection":{"value":1.8,"unit":"× size change","rationale":"Broadcast clips that zoomed 2.3–2.4× during the stroke were classified correctly only 2 times in 3 (a defence read as a drive). Past this zoom no different shot is named; the result is uncertain instead."},"stroke.min_stride":{"value":0.12,"unit":"× stature","rationale":"A front-foot movement this large counts as a stroke even when the hands are hidden."},"ffd.accept_body.min_probability":{"value":0.8,"unit":"probability","rationale":"Bat or ball not seen: the same probability bar as full evidence, plus a wider margin, near-complete body evidence and a fully visible contact."},"ffd.accept_body.min_margin":{"value":0.5,"unit":"probability","rationale":"Without the bat, a defence must beat the drive and every other shot by a wide margin (full evidence: 0.3)."},"ffd.accept_body.min_coverage":{"value":0.85,"unit":"fraction","rationale":"Nearly every body and hand signal that this camera position can show must be observed."},"ffd.accept_body.min_contact_visibility":{"value":0.7,"unit":"fraction","rationale":"A shot is decided at contact: through ±150 ms of it the stroke must be seen in this share of frames (read from the body alone: head, hips, front knee and front ankle; with bat and ball tracked: the body or the whole bat), or no verdict is given either way."},"ffd.reject.max_probability":{"value":0.12,"unit":"probability","rationale":"Below this, the clip is confidently not a front-foot defence."},"ffd.reject.min_alternative":{"value":0.5,"unit":"probability","rationale":"A different shot is reported only when one alternative (a shot, or a family of related shots) holds at least half the probability; probability spread over unrelated shots means the movement fits none of them: uncertain."},"ffd.reject.min_evidence_coverage":{"value":0.45,"unit":"fraction","rationale":"Rejection may rest on fewer modalities than acceptance."},"ffd.named_label.min_probability":{"value":0.55,"unit":"probability","rationale":"Name the alternative shot only when it clearly leads."},"photo.min_forward_spread":{"value":0.25,"unit":"× stature","rationale":"Feet no further apart than a stance (about 0.2–0.3 × height) mean the front foot hasn''t stepped toward the ball."},"photo.min_resemblance":{"value":0.35,"unit":"share of checks","rationale":"Below about a third of the position checks met, the photo doesn''t resemble a defence (a pull or a cut at contact meets one or two)."},"index.min_domains":{"value":5,"unit":"domains","rationale":"A composite needs most domains measured."},"baseline.min_deliveries":{"value":6,"unit":"valid deliveries","rationale":"Fewer than six cannot describe a personal distribution."}},"metrics":[{"id":"line_head","name":"Head over the ball","domain":"alignment","unit":"× stature","decimals":2,"phase":"Contact","meaning":"Where your head is relative to your front ankle at contact. Side-on: how far forward of it (toward the bowler). From either end of the pitch: how far toward the off side of it, over the line of the ball.","relevance":"The head leads the line. Over the ball, the eyes see its last movement and the bat comes down under them; behind it or falling away, the bat follows the head off the line.","range":{"lo":-0.03,"hi":0.16},"rangeSideways":{"lo":0.03,"hi":0.23},"requires":["body","contact"],"weight":1.4,"direction":"band","basis":"Side-on: coaching geometry (head over the front toe, front shoulder over the knee, knee over the foot), checked against side-on photos of defences. Provisional."},{"id":"line_shoulder","name":"Front shoulder in the line","domain":"alignment","unit":"× stature","decimals":2,"phase":"Contact","meaning":"Where your front shoulder is relative to your front ankle at contact (side-on: forward of it; from either end: toward the off side of it).","relevance":"The front shoulder leads the body into the line of the ball and stays over the front foot; a shoulder left behind or swinging away pulls the bat across the line.","range":{"lo":-0.03,"hi":0.11},"rangeSideways":{"lo":-0.07,"hi":0.11},"requires":["body","contact"],"weight":1.3,"direction":"band","basis":"Side-on: coaching geometry (head over the front toe, front shoulder over the knee, knee over the foot), checked against side-on photos of defences. Provisional."},{"id":"line_knee","name":"Front knee over the front foot","domain":"alignment","unit":"× stature","decimals":2,"phase":"Contact","meaning":"Where your front knee is relative to your front ankle at contact (side-on: forward of it; from either end: toward the off side of it).","relevance":"The knee over the foot is the base of the line: it takes the weight forward and lets the head go over the ball without falling.","range":{"lo":-0.04,"hi":0.05},"rangeSideways":{"lo":-0.07,"hi":0.06},"requires":["body","contact"],"weight":1.1,"direction":"band","basis":"Side-on: coaching geometry (head over the front toe, front shoulder over the knee, knee over the foot), checked against side-on photos of defences. Provisional."},{"id":"line_held","name":"Held in line to contact","domain":"alignment","unit":"share of frames","decimals":2,"phase":"Front-foot landing → contact","meaning":"From the moment your front foot lands until the bat meets the ball, the share of frames in which your head, front shoulder and front knee are all in line over the front foot.","relevance":"The line has to be there when the ball arrives, not just pass through it: a line that is still forming at contact means the head or the shoulder is still moving as you play.","range":{"lo":0.7,"hi":1},"requires":["body","contact"],"weight":1.2,"direction":"higher","only":"video","basis":"Coaching: the head and front shoulder lead into the line and hold it until contact. Provisional threshold."},{"id":"sync_spread","name":"Foot, knee and shoulder together","domain":"alignment","unit":"ms","decimals":0,"phase":"Stride → contact","meaning":"The time between the first and the last of your front foot, front knee and front shoulder arriving in their set position. The knee arrives when it has taken your weight: when your hips stop lowering.","relevance":"The three move as one: the foot lands as the knee takes the weight and the shoulder arrives over it. One arriving well before or after the others breaks the line.","range":{"lo":0,"hi":150},"requires":["body","contact"],"weight":1,"direction":"lower","only":"video","basis":"Coaching: front foot, front knee and front shoulder arrive together. Provisional threshold: 150 ms is about one stride''s settling time; one frame of measurement error each."},{"id":"set_late","name":"Set before the ball arrives","domain":"alignment","unit":"ms","decimals":0,"phase":"Contact","meaning":"How long after contact the last of your front foot, front knee and front shoulder was still moving into position. 0 = all set before the bat met the ball.","relevance":"Skilled batters land the front foot and settle before contact; still arriving as the ball is played means the position is set by the ball, not by you.","range":{"lo":0,"hi":70},"requires":["body","contact"],"weight":1,"direction":"lower","only":"video","basis":"Skilled batters'' front foot lands just before contact. Allowance: about two frames at 30 fps for the contact estimate. Provisional."},{"id":"decision_timing","name":"Decision timing","domain":"setup","unit":"ms","decimals":0,"phase":"Bounce","meaning":"When the front foot starts moving, relative to the ball''s bounce. Negative means before bounce.","relevance":"Early commitment gives time to get the head and front foot to the line of the ball.","range":{"lo":-260,"hi":40},"requires":["body","ball","bounce","timing"],"weight":1,"direction":"band"},{"id":"stride_length","name":"Front-foot stride","domain":"footwork","unit":"× stature","decimals":2,"phase":"Front-foot plant","meaning":"How far the front foot travels toward the bowler, as a fraction of standing height.","relevance":"Reaching toward the pitch of the ball smothers movement off the surface.","range":{"lo":0.3,"hi":0.46},"requires":["body"],"weight":1.2,"direction":"band","only":"video","basis":"Coaching: stride to the pitch of the ball. Provisional numbers."},{"id":"foot_spread","name":"Front-foot stride (foot to foot)","domain":"footwork","unit":"× stature","decimals":2,"phase":"Contact","meaning":"Distance from the back ankle to the front ankle along the pitch, as a fraction of standing height.","relevance":"A long stride gets the front foot and head to the pitch of the ball.","range":{"lo":0.5,"hi":1},"requires":["body","contact","side_view"],"weight":0,"direction":"band","only":"photo","basis":"Stance width (about 0.2–0.3 × height) plus the 0.30–0.46 front-foot stride; above 1.0 the batter is over-stretched. Provisional."},{"id":"front_knee_flexion","name":"Front-knee angle","domain":"footwork","unit":"°","decimals":0,"phase":"Contact","meaning":"Interior angle at the front knee (180° = straight leg).","relevance":"A flexed front knee lets the head travel forward and down over the ball.","range":{"lo":90,"hi":152},"requires":["body","contact"],"weight":1,"direction":"band","basis":"Coaching: a clearly bent front knee (under ~150°). Below 90° the hips sink below the knee, a collapsed base. Skilled batters get lower and further forward than less-skilled ones (Taliep et al., 2007)."},{"id":"back_knee_extension","name":"Back leg","domain":"footwork","unit":"°","decimals":0,"phase":"Contact","meaning":"Interior angle at the back knee (180° = straight leg).","relevance":"A long back leg, heel lifting, lets the weight go fully onto the front foot.","range":{"lo":135,"hi":180},"requires":["body","contact","side_view"],"weight":0.6,"direction":"band","basis":"Coaching: back leg extended, back heel raised. Provisional numbers."},{"id":"weight_forward","name":"Weight over front foot","domain":"footwork","unit":"0–1","decimals":2,"phase":"Contact","meaning":"Where the estimated centre of mass sits between back foot (0) and front foot (1).","relevance":"Weight forward keeps the bat and head over the ball rather than falling back.","range":{"lo":0.55,"hi":0.9},"requires":["body","contact"],"weight":1,"direction":"band","basis":"Coaching: weight over the front knee. Skilled batters keep their centre of mass further forward at contact (Taliep et al., 2007). Provisional numbers."},{"id":"head_speed_contact","name":"Head stillness at contact","domain":"head_trunk","unit":"× stature/s","decimals":2,"phase":"±100 ms around contact","meaning":"Net head travel across the 200 ms around contact, as speed. Lower is stiller.","relevance":"A still head improves judgement of line and bounce at the moment of contact.","range":{"lo":0,"hi":0.32},"requires":["body","contact","timing"],"weight":1.2,"direction":"lower"},{"id":"trunk_inclination","name":"Forward trunk lean","domain":"head_trunk","unit":"°","decimals":0,"phase":"Contact","meaning":"Angle of the hip-to-shoulder line from vertical, leaning toward the bowler.","relevance":"Leaning into the shot takes the head forward over the ball.","range":{"lo":12,"hi":55},"requires":["body","contact"],"weight":0.8,"direction":"band","basis":"Coaching: lean into the ball. Less-skilled batters stay more upright at contact (Taliep et al., 2007); falling over is caught by the head and weight checks. Provisional numbers."},{"id":"hands_ahead_of_knee","name":"Hands ahead of front knee","domain":"bat_contact","unit":"× stature","decimals":2,"phase":"Contact","meaning":"Forward distance of the hands from the front knee. Positive = hands ahead, bat angled down.","relevance":"Hands ahead of the pad angle the bat down, so the ball goes into the ground.","range":{"lo":0,"hi":0.3},"requires":["body","contact","side_view"],"weight":0.8,"direction":"band","basis":"The defence meets the ball with the bat about 27° forward of vertical (Stretch et al., 1998), which puts the hands about 0.1–0.25 × height ahead of a ball met beside the front knee."},{"id":"pelvis_thorax_separation","name":"Pelvis–thorax separation","domain":"sequence","unit":"°","decimals":0,"phase":"Downswing","meaning":"Peak rotation difference between hip and shoulder axes.","relevance":"Large separation suggests an attacking, rotational stroke rather than a block.","range":{"lo":0,"hi":20},"requires":["body","depth"],"weight":0.6,"direction":"lower"},{"id":"bat_angle_contact","name":"Bat angle at contact","domain":"bat_contact","unit":"° from vertical","decimals":0,"phase":"Contact","meaning":"How far the bat is tilted from vertical when it meets the ball.","relevance":"An angled bat, handle ahead of the blade, sends the ball down into the ground.","range":{"lo":14,"hi":40},"requires":["bat","contact"],"weight":1.2,"direction":"band","basis":"Measured in forward defences: 62.6 ± 6.5° from horizontal, i.e. about 27° forward of vertical (drive: 78°) (Stretch et al., 1998). Range: mean ± 2 SD."},{"id":"contact_ahead_of_knee","name":"Contact point vs front knee","domain":"bat_contact","unit":"× stature","decimals":2,"phase":"Contact","meaning":"Forward distance of the contact point from the front knee. Negative = beside or behind the pad.","relevance":"Meeting the ball beside or just ahead of the front pad keeps it under the eyes.","range":{"lo":-0.06,"hi":0.1},"requires":["body","bat","contact","side_view"],"weight":1,"direction":"band"},{"id":"bat_speed_contact","name":"Bat speed at contact","domain":"bat_contact","unit":"m/s","decimals":1,"phase":"Contact","meaning":"Speed of the bat''s sweet-spot region at contact.","relevance":"A defence absorbs the ball; high bat speed suggests a drive or pushed defence.","range":{"lo":0,"hi":6},"requires":["bat","contact","timing","scale","side_view"],"weight":1,"direction":"lower"},{"id":"bat_pad_gap","name":"Bat–pad gap","domain":"bat_contact","unit":"cm","decimals":0,"phase":"Contact","meaning":"Smallest lateral gap between bat and front pad near contact.","relevance":"A closed gap stops the ball deflecting between bat and pad.","range":{"lo":0,"hi":12},"requires":["body","bat","depth"],"weight":0.8,"direction":"lower"},{"id":"ball_exit_speed","name":"Ball speed off the bat","domain":"outcome","unit":"m/s","decimals":1,"phase":"Post-contact","meaning":"Speed of the ball in the first frames after contact.","relevance":"A controlled defence deadens the ball; a fast exit suggests hard hands.","range":{"lo":0,"hi":8},"requires":["ball","contact","timing","scale","side_view"],"weight":0.9,"direction":"lower"},{"id":"repeatability","name":"Repeatability","domain":"outcome","unit":"","decimals":2,"phase":"Across deliveries","meaning":"How consistent the key measures are across your valid deliveries.","relevance":"Repeatable movement is what turns practice into match performance.","range":null,"requires":["baseline"],"weight":0,"direction":"higher"}],"frontal_metrics":[{"id":"balance_over_feet","name":"Balanced over your feet","domain":"footwork","unit":"× stature","decimals":2,"phase":"Contact","meaning":"How far your estimated centre of mass sits sideways outside your feet (heels to toes) at contact, seen from the bowler''s end. 0 = over them.","relevance":"A defence is played from a stable base: with your weight outside your feet you are falling over to the off side or away to the leg side, and the bat follows.","range":{"lo":0,"hi":0.02},"requires":["body","contact"],"weight":1.1,"direction":"lower"}],"frontal_ungraded":["stride_length","weight_forward","trunk_inclination","front_knee_flexion","head_speed_contact","decision_timing"],"frontal_withheld":["stride_length","weight_forward","trunk_inclination","front_knee_flexion"]}'::jsonb)
on conflict (hash) do nothing;
